From abac8ca3552b4818017bb0ce11aaf22a1fb6f07a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:26:16 +0100
Subject: [PATCH] alternatecalendar: reload dates when the calendar system
 changes

updateSettings() cleared the last loaded range in init() and then asked
to load that now empty range, so open views kept showing the old
calendar's dates. Remember the range before clearing it, then reload it.

BUG: 486561
---
 .../alternatecalendar/alternatecalendarplugin.cpp             | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)

diff --git a/plasmacalendarplugins/alternatecalendar/alternatecalendarplugin.cpp b/plasmacalendarplugins/alternatecalendar/alternatecalendarplugin.cpp
index d0e06ce59..424d575f9 100644
--- a/plasmacalendarplugins/alternatecalendar/alternatecalendarplugin.cpp
+++ b/plasmacalendarplugins/alternatecalendar/alternatecalendarplugin.cpp
@@ -116,8 +116,10 @@ void AlternateCalendarPlugin::updateSettings(const KConfigGroup &configGroup)
     if (configGroup.config()->name() != "plasma_calendar_alternatecalendar"_L1) {
         return;
     }
+    const QDate startDate = m_lastStartDate;
+    const QDate endDate = m_lastEndDate;
     init();
-    loadEventsForDateRange(m_lastStartDate, m_lastEndDate);
+    loadEventsForDateRange(startDate, endDate);
 }

 void AlternateCalendarPlugin::init()
-- 
