 applets/digital-clock/DigitalClock.qml        | 13 ++++
 applets/digital-clock/configAppearance.qml    | 12 ++++
 applets/digital-clock/main.xml                |  2 +-
 components/calendar/daysmodel.cpp             |  4 +-
 6 files changed, 88 insertions(+), 3 deletions(-)
 create mode 100644 applets/digital-clock/AlternateCalendarDate.qml

diff --git a/applets/digital-clock/AlternateCalendarDate.qml b/applets/digital-clock/AlternateCalendarDate.qml
new file mode 100644
index 0000000000..a5e9be7230
--- /dev/null
+++ b/applets/digital-clock/AlternateCalendarDate.qml
@@ -0,0 +1,59 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+pragma ComponentBehavior: Bound
+
+import QtQuick
+
+import org.kde.plasma.workspace.calendar as PlasmaCalendar
+
+// The date as written in the alternate calendar system, as shown in the calendar's header
+QtObject {
+    id: root
+
+    property date date
+    property bool active: false
+
+    readonly property string text: active ? label : ""
+
+    property string label: ""
+
+    readonly property PlasmaCalendar.EventPluginsManager pluginsManager: PlasmaCalendar.EventPluginsManager {
+        enabledPlugins: root.active ? ["alternatecalendar"] : []
+    }
+
+    readonly property PlasmaCalendar.Calendar backend: PlasmaCalendar.Calendar {
+        days: root.active ? 7 : 0
+        weeks: root.active ? 6 : 0
+        today: root.date
+
+        // Keep today in the loaded range when the month changes
+        onTodayChanged: resetToToday()
+
+        Component.onCompleted: daysModel.setPluginsManager(root.pluginsManager)
+    }
+
+    readonly property Instantiator days: Instantiator {
+        active: root.active
+        model: root.backend.daysModel
+
+        delegate: QtObject {
+            required property int dayNumber
+            required property int monthNumber
+            required property int yearNumber
+            required property var subLabel
+
+            readonly property bool isToday: dayNumber === root.date.getDate()
+                && monthNumber === root.date.getMonth() + 1
+                && yearNumber === root.date.getFullYear()
+            readonly property string todayLabel: isToday ? (subLabel ?? "") : ""
+
+            onIsTodayChanged: if (isToday) { root.label = todayLabel; }
+            onTodayLabelChanged: if (isToday) { root.label = todayLabel; }
+            Component.onCompleted: if (isToday) { root.label = todayLabel; }
+        }
+    }
+}
